import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
class OrderController {

    record OrderResponse(String id, String customerId, BigDecimal amount, String currency, String status) {
        static OrderResponse from(Order order) {
            return new OrderResponse(
                    order.id(),
                    order.customerId(),
                    order.amount().amount(),
                    String.valueOf(order.amount().currency()),
                    order.status().name());
        }
    }

    private final ConsultOrder consultOrder;
    private final CancelOrder cancelOrder;

    OrderController(ConsultOrder consultOrder, CancelOrder cancelOrder) {
        this.consultOrder = consultOrder;
        this.cancelOrder = cancelOrder;
    }

    @GetMapping("/orders/{id}")
    OrderResponse get(@PathVariable String id, @RequestHeader("X-Customer-Id") String customerId) {
        return OrderResponse.from(consultOrder.handle(id, customerId));
    }

    @PostMapping("/orders/{id}/cancel")
    OrderResponse cancel(@PathVariable String id, @RequestHeader("X-Customer-Id") String customerId) {
        return OrderResponse.from(cancelOrder.handle(id, customerId));
    }

    // Foreign orders are reported as missing so their existence is not leaked.
    @ExceptionHandler(OrderNotFoundException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    void notFound() {}

    @ExceptionHandler(OrderNotCancellableException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    void notCancellable() {}
}
